import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void max_reduce_kernel_vec4(
    const float* __restrict__ input,
    float* __restrict__ output,
    long outer_size,
    long dim_size,
    long inner_vec,
    long inner_size)
{
    long total = outer_size * inner_vec;
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long stride = blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        long outer = idx / inner_vec;
        long inner_block = idx % inner_vec;
        long inner = inner_block * 4;
        long base = outer * dim_size * inner_size + inner;
        float4 max_val = make_float4(-FLT_MAX, -FLT_MAX, -FLT_MAX, -FLT_MAX);
        #pragma unroll 4
        for (long k = 0; k < dim_size; ++k) {
            float4 v = *reinterpret_cast<const float4*>(&input[base + k * inner_size]);
            max_val.x = v.x > max_val.x ? v.x : max_val.x;
            max_val.y = v.y > max_val.y ? v.y : max_val.y;
            max_val.z = v.z > max_val.z ? v.z : max_val.z;
            max_val.w = v.w > max_val.w ? v.w : max_val.w;
        }
        float4* out_ptr = reinterpret_cast<float4*>(&output[outer * inner_size + inner]);
        *out_ptr = max_val;
    }
}
__global__ void max_reduce_kernel_scalar_tail(
    const float* __restrict__ input,
    float* __restrict__ output,
    long outer_size,
    long dim_size,
    long inner_size,
    long inner_start)
{
    long tail_size = inner_size - inner_start;
    long total = outer_size * tail_size;
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long stride = blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        long outer = idx / tail_size;
        long inner_off = idx % tail_size;
        long inner = inner_start + inner_off;
        long base = outer * dim_size * inner_size + inner;
        float max_val = -FLT_MAX;
        #pragma unroll 8
        for (long k = 0; k < dim_size; ++k) {
            float v = __ldg(&input[base + k * inner_size]);
            max_val = v > max_val ? v : max_val;
        }
        output[outer * inner_size + inner] = max_val;
    }
}
torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim) {
    x = x.contiguous();
    int64_t ndim = x.dim();
    if (dim < 0) dim += ndim;
    int64_t outer_size = 1;
    for (int64_t i = 0; i < dim; ++i) outer_size *= x.size(i);
    int64_t dim_size = x.size(dim);
    int64_t inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner_size *= x.size(i);
    std::vector<int64_t> out_shape;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) out_shape.push_back(x.size(i));
    }
    auto output = torch::empty(out_shape, x.options());
    int64_t inner_vec = (inner_size % 4 == 0) ? (inner_size / 4) : 0;
    int64_t inner_rem_start = inner_vec * 4;
    int64_t tail_size = inner_size - inner_rem_start;
    int threads = 256;
    if (inner_vec > 0) {
        long total_vec = outer_size * inner_vec;
        int blocks = (total_vec + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        max_reduce_kernel_vec4<<<blocks, threads>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            outer_size,
            dim_size,
            inner_vec,
            inner_size
        );
    }
    if (tail_size > 0) {
        long total_tail = outer_size * tail_size;
        int blocks_tail = (total_tail + threads - 1) / threads;
        if (blocks_tail > 65535) blocks_tail = 65535;
        if (blocks_tail < 1) blocks_tail = 1;
        max_reduce_kernel_scalar_tail<<<blocks_tail, threads>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            outer_size,
            dim_size,
            inner_size,
            inner_rem_start
        );
    }
    return output;
}
"""

max_reduce_cpp_source = r"""
torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim);
"""

max_reduce_module = load_inline(
    name="max_reduce_module",
    cpp_sources=max_reduce_cpp_source,
    cuda_sources=max_reduce_source,
    functions=["max_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.max_reduce = max_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.max_reduce.max_reduce_cuda(x, self.dim)


batch_size = 128
dim1 = 4096
dim2 = 4095

def get_inputs():
    x = torch.rand(batch_size, dim1, dim2).cuda()
    return [x]

def get_init_inputs():
    return [1]

